import {studyStats,studyLevels,wordTopics,sentenceScenes,studyWords,studySentences,studyGrammar,filterStudyItems,getStudyQuestion} from './study-data.js';
import {answerCard} from './practice-ui.js';

const labels=(T)=>({vocabulary:T('Kelimeler','Vocabulary'),sentences:T('Cümleler','Sentences'),grammar:T('Gramer','Grammar')});
export function studyLaunches({T,icon}) {
 return `<section class="study-launch-section"><div class="section-top"><div><p class="eyebrow">N5 → N1</p><h2>${T('Kelimeyi öğren. Cümlede kullan.','Learn a word. Use it in a sentence.')}</h2></div><span class="small muted">${T('Seviye ve konu seçerek çalış','Study by level and topic')}</span></div><div class="study-launch-grid">${[['vocabulary','語',T(`${studyStats.words} kelime · ${studyStats.topics} başlık`,`${studyStats.words} words · ${studyStats.topics} topics`)],['sentences','話',T(`${studyStats.sentences} cümle · ${studyStats.scenes} farklı ortam`,`${studyStats.sentences} sentences · ${studyStats.scenes} settings`)],['grammar','文',T(`${studyStats.grammar} konu · Açıklama ve alıştırma`,`${studyStats.grammar} patterns · Notes and practice`)]].map(([kind,glyph,desc])=>`<a href="#${kind}" class="study-launch"><span lang="ja">${glyph}</span><h3>${labels(T)[kind]}</h3><p>${desc}</p>${icon('arrow')}</a>`).join('')}</div></section>`;
}
export function studyPage(state,kind,u) {
 const {T,L,esc,icon}=u,c=state.learning[kind],items=filterStudyItems(kind,c),item=items.find(i=>i.id===c.selectedId)||items[0];
 const names=labels(T),groups=kind==='vocabulary'?wordTopics:kind==='sentences'?sentenceScenes:[];
 const session=state.learning.session?.kind===kind?state.learning.session:null;
 const heading={vocabulary:T('Bir kelime, yeni bir bağlantı.','One word, a new connection.'),sentences:T('Hayatın içinden Japonca.','Japanese for real situations.'),grammar:T('Cümlelerin nasıl kurulduğunu keşfet.','Discover how sentences fit together.')}[kind];
 const config=`<section class="study-filters" aria-label="${T('Çalışma filtreleri','Study filters')}"><div class="study-levels" aria-label="${T('Çalışma düzeyi','Study level')}">${['all',...studyLevels].map(level=>`<button data-action="study-level" data-kind="${kind}" data-level="${level}" aria-pressed="${c.level===level}">${level==='all'?T('Tümü','All'):level}</button>`).join('')}</div><div class="study-filter-row">${groups.length?`<label>${kind==='vocabulary'?T('Konu','Topic'):T('Ortam','Setting')}<select data-study-kind="${kind}" data-study="category"><option value="all">${T('Tüm başlıklar','All topics')}</option>${groups.map(g=>`<option value="${g.id}" ${c.category===g.id?'selected':''}>${esc(g[state.settings.language])}</option>`).join('')}</select></label>`:''}<form data-form="study-search" data-kind="${kind}"><label for="study-search">${T('İçerikte ara','Search content')}</label><div class="study-search-row"><input id="study-search" name="search" type="search" value="${esc(c.search)}" maxlength="100" placeholder="${T('Japonca, Türkçe veya İngilizce…','Japanese, Turkish or English…')}"><button class="btn secondary" type="submit">${T('Ara','Search')}</button></div></form>${c.search?`<button class="subtle-link" data-action="study-clear" data-kind="${kind}">${T('Aramayı temizle','Clear search')}</button>`:''}</div>${kind==='vocabulary'?`<div class="study-topic-note small muted">${esc(L(groups.find(g=>g.id===c.category)?.note || {tr:'Kelimeleri konuya göre keşfet; örnek cümlelerini de incele.',en:'Explore words by topic and read their examples.'}))}</div>`:''}</section>`;
 const start=`<div class="study-practice-controls">${kind==='vocabulary'?`<label>${T('Alıştırma türü','Exercise type')}<select data-study-kind="${kind}" data-study="mode">${[['meaning',T('Anlamını seç','Choose the meaning')],['reading',T('Okunuşunu yaz','Type the reading')],['writing',T('Japonca yaz','Write in Japanese')]].map(([id,label])=>`<option value="${id}" ${c.mode===id?'selected':''}>${label}</option>`).join('')}</select></label>`:''}<button class="btn primary" data-action="study-start" data-kind="${kind}" ${items.length?'':'disabled'}>${T('Bu seçkiyle pratik yap','Practice this selection')}${icon('arrow')}</button><span class="small muted">${Math.min(10,items.length)} ${T('soru · Her tur karışık',Math.min(10,items.length)===1?'question · Shuffled each round':'questions · Shuffled each round')}</span></div>`;
 let stage='';
 if(session?.phase==='exercise'){
  const q=getStudyQuestion(session.ids[session.index]),event=state.events.find(e=>e.id===session.feedback);
  stage=q?`<section class="study-session"><div class="section-top"><h2 tabindex="-1" id="study-stage-title">${names[kind]} · ${session.index+1} / ${session.ids.length}</h2><button class="subtle-link" data-action="study-close">${T('Kartlara dön','Back to cards')}</button></div><p class="small muted">${T('Bu tur başladığın seçkiyi kullanır. Cevapların tekrar planına kaydedilir.','This round uses your starting selection. Answers are saved to your review schedule.')}</p>${answerCard(q,event,u,{form:'study-answer',next:'study-next',practiceClass:'study-question'})}</section>`:'';
 }else if(session?.phase==='done'){
  const events=state.events.filter(e=>session.eventIds.includes(e.id));
  stage=`<section class="study-session study-complete"><span lang="ja">おつかれさま</span><h2 tabindex="-1" id="study-stage-title">${T('Bu tur tamam.','Round complete.')}</h2><p>${events.filter(e=>e.correct).length} / ${events.length} ${T('doğru cevap. Cevapların tekrar planında.','correct answers. Your answers are in the review schedule.')}</p><div class="button-row"><button class="btn primary" data-action="study-close">${T('Kartlara dön','Back to cards')}</button><a class="btn secondary" href="#review">${T('Tekrarlara git','Go to reviews')}</a></div></section>`;
 }else if(!item){stage=`<section class="study-empty"><h2>${T('Bu seçkide sonuç yok.','No results in this selection.')}</h2><p>${T('Aramayı temizle veya başka bir düzey seç.','Clear your search or choose another level.')}</p><button class="btn secondary" data-action="study-reset" data-kind="${kind}">${T('Filtreleri sıfırla','Reset filters')}</button></section>`;
 }else{
  const index=items.indexOf(item),isWord=kind==='vocabulary',isGrammar=kind==='grammar';
  const written=isWord?item.written:isGrammar?item.form:item.ja,example=isWord||isGrammar?item.example:null;
  const saved=Object.values(state.skillStates).some(s=>s.itemId===`study-${item.id}`);
  stage=`<div class="study-browser"><aside class="study-item-list" aria-label="${T('İçerik listesi','Content list')}"><div class="study-list-heading">${items.length} ${T('içerik',items.length===1?'item':'items')}</div>${items.map(i=>`<button data-action="study-select" data-kind="${kind}" data-item="${i.id}" aria-pressed="${i.id===item.id}"><span lang="ja">${esc(isWord?i.written:isGrammar?i.form:i.ja)}</span><small>${i.level} · ${esc(isWord?L(i.meaning):isGrammar?L(i.title):L(i.translation))}</small></button>`).join('')}</aside><article class="study-detail"><div class="section-top"><span class="level-pill">${item.level} · ${names[kind]}</span><span class="small muted">${index+1} / ${items.length}</span></div><h2 class="study-written ${isWord?'word':''}" lang="ja">${esc(written)}</h2>${isWord?`<p class="study-meaning">${esc(L(item.meaning))}</p>`:isGrammar?`<h3>${esc(L(item.title))}</h3><p class="study-explanation">${esc(L(item.explanation))}</p>`:`<p class="study-meaning">${esc(L(item.translation))}</p><p class="study-register">${T('Kullanım','Usage')}: ${esc(L(item.note))}</p>`}<label class="toggle study-reading-toggle"><input type="checkbox" data-study-kind="${kind}" data-study="showReading" ${c.showReading?'checked':''}><span>${T('Kana okunuşunu göster','Show kana reading')}</span></label>${c.showReading?`<p class="study-reading" lang="ja">${esc(isWord?item.reading:isGrammar?item.example.reading:item.reading)}</p>`:''}${example?`<div class="study-example"><p class="eyebrow">${T('ÖRNEK CÜMLE','EXAMPLE SENTENCE')}</p><p lang="ja">${esc(example.ja)}</p>${c.showReading&&isWord?`<p class="study-example-reading" lang="ja">${esc(example.reading)}</p>`:''}<p>${esc(L(example.translation))}</p></div>`:''}<div class="study-card-actions"><button class="btn secondary" data-action="study-save" data-kind="${kind}" data-item="${item.id}">${saved?T('Tekrar listesinde','In review list'):T('Tekrara ekle','Save for review')}${icon('repeat')}</button><div class="study-pager"><button data-action="study-select" data-kind="${kind}" data-item="${items[index-1]?.id||''}" ${index===0?'disabled':''} aria-label="${T('Önceki kart','Previous card')}">←</button><button data-action="study-select" data-kind="${kind}" data-item="${items[index+1]?.id||''}" ${index===items.length-1?'disabled':''} aria-label="${T('Sonraki kart','Next card')}">→</button></div></div><p class="small muted">${isWord?T('Kaydetmek anlam ve okunuş kartlarını ekler; doğru cevap sayılmaz.','Saving adds meaning and reading cards; it does not count as a correct answer.'):T('Kaydetmek boşluk doldurma kartını ekler; doğru cevap sayılmaz.','Saving adds a gap-fill card; it does not count as a correct answer.')}</p></article></div>`;
 }
 return `<div class="page-heading"><p class="eyebrow">${T('ADIM ADIM ÇALIŞ','STUDY STEP BY STEP')} · N5–N1</p><h1 tabindex="-1">${heading}</h1><p class="muted">${T('Başlığını ve düzeyini seç. Kartları incele, sonra kendini dene.','Choose a topic and level. Explore the cards, then test yourself.')}</p></div><nav class="study-tabs" aria-label="${T('Çalışma alanları','Study areas')}">${Object.entries(names).map(([id,name])=>`<a href="#${id}" ${id===kind?'aria-current="page"':''}>${name}</a>`).join('')}</nav><p class="study-level-note">${T(`Çalışma paketi: ${studyStats.words} kelime, ${studyStats.sentences} cümle, ${studyStats.grammar} gramer konusu. N5 en kolay, N1 en ileri çalışma bandıdır. Etiketler yaklaşık düzeydir; eksiksiz veya resmî JLPT listesi değildir.`,`Study pack: ${studyStats.words} words, ${studyStats.sentences} sentences, ${studyStats.grammar} grammar patterns. N5 is the easiest and N1 the most advanced study band. Labels are approximate; this is not a complete or official JLPT list.`)}</p>${config}${start}${stage}`;
}
